static int
setup_module(PyObject *m) {
    PyObject *d;
    PyObject *v;
    int vn;

    /* Ready object types */
    if (PyType_Ready(&CmsProfile_Type) < 0 || PyType_Ready(&CmsTransform_Type) < 0) {
        return -1;
    }

    if (PyModule_AddObjectRef(m, "CmsProfile", (PyObject *)&CmsProfile_Type) < 0 ||
        PyModule_AddObjectRef(m, "CmsTransform", (PyObject *)&CmsTransform_Type) < 0) {
        return -1;
    }

    PyDateTime_IMPORT;

    d = PyModule_GetDict(m);

    /* this check is also in PIL.features.pilinfo() */
#if LCMS_VERSION < 2070
    vn = LCMS_VERSION;
#else
    vn = cmsGetEncodedCMMversion();
#endif
    if (vn % 10) {
        v = PyUnicode_FromFormat("%d.%d.%d", vn / 1000, (vn / 10) % 100, vn % 10);
    } else {
        v = PyUnicode_FromFormat("%d.%d", vn / 1000, (vn / 10) % 100);
    }
    if (!v) {
        return -1;
    }
    PyDict_SetItemString(d, "littlecms_version", v);
    Py_DECREF(v);

    return 0;
}

static PyModuleDef_Slot slots[] = {
    {Py_mod_exec, setup_module},
#ifdef Py_GIL_DISABLED
    {Py_mod_gil, Py_MOD_GIL_NOT_USED},
#endif
    {0, NULL}
};

PyMODINIT_FUNC
PyInit__imagingcms(void) {
    static PyModuleDef module_def = {
        PyModuleDef_HEAD_INIT,
        .m_name = "_imagingcms",
        .m_methods = pyCMSdll_methods,
        .m_slots = slots
    };

    return PyModuleDef_Init(&module_def);
}

